%%%       Programa para el cáculo de rendimiento máximo para algunos amperajesfunction y=Errendimendua(potentzia_elek,beropotentzia,Tdif,lim,p,hasierakoK,limK,paso,l,izena,kontador)    j=(Tdif-lim)/p;   l=(limK-hasierakoK)/paso;     l=round(l);  for i=0:j    for k=1:l    D(k+i*l)=(potentzia_elek(k+i*l)/beropotentzia(k+i*l))*100    Tdiferentziai=j    Korrontei=k    for k=1:l    korrontea(k)=hasierakoK+(paso*(k-1))        end         end    end     hasiera=korrontea(1)    bukaera=korrontea(l)    x=linspace(hasiera,bukaera,l)   for i=0:j    for k=1:l      aldagaibalioa=num2str(Tdif-p*i)      x=korrontea(k)      figure(kontador+(i+2))      Errendimendum(k+i*l)=D((k+i*l))     plot(x,Errendimendum(k+i*l),'-o')      xlabel("I (A)")      ylabel("Rendimiento (%)")      title(["Valores de rendimiento termoelectrico en unos amperajes concretos y a este gradiante de temperatura:",aldagaibalioa])      legend(izena,'Location','southoutside')      legend('boxoff')      grid on      hold on     end     end              
endfunction
